CREATE UNIQUE INDEX movie_title_uq ON public.movie(lower(btrim(title)));
CREATE FUNCTION public.create_movie(p_title text,p_rating text,p_running_minutes int,p_genre text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_title text:=btrim(p_title); v_genre text:=btrim(p_genre); v_id uuid; BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_ONLY: Only administrators can do this.'; END IF; IF v_title IS NULL OR v_title='' OR p_rating IS NULL OR btrim(p_rating)='' OR p_running_minutes IS NULL OR v_genre IS NULL OR v_genre='' THEN RAISE EXCEPTION 'MOVIE_FIELD_REQUIRED: Fill in the title, rating, running time and genre.'; END IF; IF p_rating NOT IN('ALL','12','15','19') THEN RAISE EXCEPTION 'MOVIE_RATING_INVALID: Choose a rating of ALL, 12, 15 or 19.'; END IF; IF p_running_minutes<=0 THEN RAISE EXCEPTION 'MOVIE_RUNNING_TIME_INVALID: Running time must be a positive number of minutes.'; END IF; IF EXISTS(SELECT 1 FROM public.movie m WHERE lower(btrim(m.title))=lower(v_title)) THEN RAISE EXCEPTION 'MOVIE_TITLE_TAKEN: A movie with this title is already registered.'; END IF; INSERT INTO public.movie(title,rating,running_minutes,genre) VALUES(v_title,p_rating,p_running_minutes,v_genre) RETURNING id INTO v_id; RETURN v_id; EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'MOVIE_TITLE_TAKEN: A movie with this title is already registered.'; END $$;
CREATE FUNCTION public.create_screening(p_movie_id uuid,p_screen_id uuid,p_starts_at timestamptz,p_price int) RETURNS TABLE(screening_id uuid,ends_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_minutes int; v_end timestamptz; v_overlap public.screening%ROWTYPE; v_id uuid; BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_ONLY: Only administrators can do this.'; END IF; PERFORM pg_advisory_xact_lock(hashtext(p_screen_id::text)); SELECT m.running_minutes INTO v_minutes FROM public.movie m WHERE m.id=p_movie_id; IF NOT FOUND THEN RAISE EXCEPTION 'MOVIE_NOT_FOUND: The movie does not exist.'; END IF; IF NOT EXISTS(SELECT 1 FROM public.screen sc WHERE sc.id=p_screen_id) THEN RAISE EXCEPTION 'SCREEN_NOT_FOUND: The screen does not exist.'; END IF; IF NOT EXISTS(SELECT 1 FROM public.seat s WHERE s.screen_id=p_screen_id) THEN RAISE EXCEPTION 'SCREEN_HAS_NO_SEATS: This screen has no seats. Add its seats in Theatre setup first.'; END IF; IF p_price IS NULL OR p_price<=0 THEN RAISE EXCEPTION 'PRICE_INVALID: Price must be a positive whole number of won.'; END IF; IF p_starts_at IS NULL OR p_starts_at<now() THEN RAISE EXCEPTION 'START_IN_PAST: Start time must not be earlier than % KST.',to_char(now() AT TIME ZONE 'Asia/Seoul','YYYY-MM-DD HH24:MI'); END IF; v_end:=p_starts_at+make_interval(mins=>v_minutes); SELECT ss.* INTO v_overlap FROM public.screening ss WHERE ss.screen_id=p_screen_id AND p_starts_at<ss.ends_at AND ss.starts_at<v_end ORDER BY ss.starts_at LIMIT 1; IF FOUND THEN RAISE EXCEPTION 'OVERLAP: This screen already has a screening from % to % KST.',to_char(v_overlap.starts_at AT TIME ZONE 'Asia/Seoul','YYYY-MM-DD HH24:MI'),to_char(v_overlap.ends_at AT TIME ZONE 'Asia/Seoul','YYYY-MM-DD HH24:MI'); END IF; INSERT INTO public.screening(movie_id,screen_id,starts_at,ends_at,price) VALUES(p_movie_id,p_screen_id,p_starts_at,v_end,p_price) RETURNING id INTO v_id; RETURN QUERY SELECT v_id,v_end; END $$;
CREATE FUNCTION public.get_schedule(p_date date) RETURNS TABLE(screening_id uuid,movie_id uuid,title text,rating text,genre text,running_minutes int,screen_name text,starts_at timestamptz,ends_at timestamptz,price int,remaining_seats int,status text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF p_date IS NULL OR p_date<(now() AT TIME ZONE 'Asia/Seoul')::date THEN RAISE EXCEPTION 'DATE_IN_PAST: You cannot view a date in the past.'; END IF; RETURN QUERY SELECT ss.id,m.id,m.title,m.rating,m.genre,m.running_minutes,sc.name,ss.starts_at,ss.ends_at,ss.price,c.remaining,CASE WHEN now()>=ss.starts_at THEN 'CLOSED' WHEN c.remaining=0 THEN 'SOLD_OUT' ELSE 'OPEN' END FROM public.screening ss JOIN public.movie m ON m.id=ss.movie_id JOIN public.screen sc ON sc.id=ss.screen_id CROSS JOIN LATERAL(SELECT ((SELECT count(*) FROM public.seat s WHERE s.screen_id=ss.screen_id)-(SELECT count(*) FROM public.booking_seat bs WHERE bs.screening_id=ss.id AND bs.is_active))::int AS remaining) c WHERE (ss.starts_at AT TIME ZONE 'Asia/Seoul')::date=p_date ORDER BY m.title,ss.starts_at; END $$;
CREATE FUNCTION public.get_schedule_dates() RETURNS TABLE(schedule_date date) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT d.day::date FROM generate_series((now() AT TIME ZONE 'Asia/Seoul')::date::timestamp,greatest((now() AT TIME ZONE 'Asia/Seoul')::date,(SELECT max((ss.starts_at AT TIME ZONE 'Asia/Seoul')::date) FROM public.screening ss))::timestamp,interval '1 day') AS d(day) $$;
REVOKE ALL ON FUNCTION public.create_movie(text,text,int,text),public.create_screening(uuid,uuid,timestamptz,int) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_movie(text,text,int,text),public.create_screening(uuid,uuid,timestamptz,int) TO authenticated;
REVOKE ALL ON FUNCTION public.get_schedule(date),public.get_schedule_dates() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.get_schedule(date),public.get_schedule_dates() TO anon,authenticated;